/**
 * SHA3-256 (FIPS 202), needed for the checksum of Tor onion addresses. A small BigInt implementation of Keccak-f[1600]:
 * it hashes a few dozen bytes once, so speed does not matter. Checked against Node's crypto in the tests.
 */
const MASK = (1n << 64n) - 1n;
const rotl = (x: bigint, n: bigint) => ((x << n) | (x >> (64n - n))) & MASK;

const ROUND_CONSTANTS: bigint[] = [];
const ROTATIONS: bigint[] = new Array(25).fill(0n);
{
    // generated by the LFSR and the walk of the specification instead of being copied as 24 + 25 magic numbers
    let lfsr = 1;
    const bit = () => {
        const out = lfsr & 1;
        lfsr = lfsr & 0x80 ? (lfsr << 1) ^ 0x71 : lfsr << 1;
        lfsr &= 0xff;
        return out;
    };
    for (let round = 0; round < 24; round++) {
        let constant = 0n;
        for (let j = 0; j < 7; j++) if (bit()) constant |= 1n << BigInt((1 << j) - 1);
        ROUND_CONSTANTS.push(constant);
    }
    let [x, y] = [1, 0];
    for (let t = 0; t < 24; t++) {
        ROTATIONS[x + 5 * y] = BigInt((((t + 1) * (t + 2)) / 2) % 64);
        [x, y] = [y, (2 * x + 3 * y) % 5];
    }
}

function keccakF(state: bigint[]): void {
    for (const constant of ROUND_CONSTANTS) {
        const c = Array.from({ length: 5 }, (_, x) => state[x] ^ state[x + 5] ^ state[x + 10] ^ state[x + 15] ^ state[x + 20]);
        for (let x = 0; x < 5; x++) {
            const d = c[(x + 4) % 5] ^ rotl(c[(x + 1) % 5], 1n);
            for (let y = 0; y < 5; y++) state[x + 5 * y] ^= d;
        }
        const moved: bigint[] = new Array(25).fill(0n);
        for (let x = 0; x < 5; x++) {
            for (let y = 0; y < 5; y++) moved[y + 5 * ((2 * x + 3 * y) % 5)] = rotl(state[x + 5 * y], ROTATIONS[x + 5 * y]);
        }
        for (let x = 0; x < 5; x++) {
            for (let y = 0; y < 5; y++) state[x + 5 * y] = moved[x + 5 * y] ^ (~moved[((x + 1) % 5) + 5 * y] & moved[((x + 2) % 5) + 5 * y] & MASK);
        }
        state[0] ^= constant;
    }
}

export function sha3_256(data: Uint8Array): Uint8Array {
    const rate = 136;
    const padded = new Uint8Array(Math.ceil((data.length + 1) / rate) * rate);
    padded.set(data);
    padded[data.length] ^= 0x06;
    padded[padded.length - 1] ^= 0x80;
    const state: bigint[] = new Array(25).fill(0n);
    for (let offset = 0; offset < padded.length; offset += rate) {
        for (let i = 0; i < rate / 8; i++) {
            let lane = 0n;
            for (let b = 7; b >= 0; b--) lane = (lane << 8n) | BigInt(padded[offset + i * 8 + b]);
            state[i] ^= lane;
        }
        keccakF(state);
    }
    const out = new Uint8Array(32);
    for (let i = 0; i < 32; i++) out[i] = Number((state[i >> 3] >> BigInt(8 * (i & 7))) & 0xffn);
    return out;
}
